package sohal.lld.hotelbooking;import sohal.lld.hotelbooking.entity.Room;import sohal.lld.hotelbooking.enums.RoomType;import java.util.List;import java.util.Map;import java.util.Optional;import java.util.concurrent.ConcurrentHashMap;public class Hotel {    private static class Holder {        private static final Hotel INSTANCE = new Hotel();    }    public static Hotel getInstance() {        return Holder.INSTANCE;    }    private Map<RoomType, List<Room>> rooms =  new ConcurrentHashMap<>();    public Optional<List<Room>> getAvailableRooms(RoomType type) {        List<Room> all = rooms.getOrDefault(type, List.of());        List<Room> available = all.stream()                .filter(Room::isAvailable)                .toList();        return available.isEmpty() ? Optional.empty() : Optional.of(available);    }}